<script setup>
import {ref,computed,onUnmounted} from 'vue'
import {api} from '../lib/api'
import {useArcade} from '../stores/arcade'
import {useStudyActivity} from '../composables/useStudyActivity'
import SourceBadge from './SourceBadge.vue'
const props=defineProps({initial:Object}),emit=defineEmits(['exit']),s=useArcade(),session=ref(props.initial),answer=ref(props.initial.draft??''),busy=ref(false),error=ref(''),q=computed(()=>session.value.question),submitted=computed(()=>session.value.answers[q.value?.id]);let alive=true
useStudyActivity(()=>!session.value.done?{kind:'community',sessionId:session.value.id}:null);onUnmounted(()=>alive=false)
async function command(action){if(busy.value)return;busy.value=true;error.value='';try{const result=await api('/quiz/'+session.value.id+'/'+action,{method:'POST',body:action==='submit'?{questionId:q.value.id,answer:answer.value}:{}});if(alive)session.value=result.session??result;await s.refresh()}catch(e){if(alive)error.value=e.message}finally{if(alive)busy.value=false}}
const correct=computed(()=>q.value?.type==='multiple'?q.value.options.find(o=>o.id===q.value.correctOptionId)?.text:q.value?.correctAnswer)
</script>
<template><section class="panel community-runner"><SourceBadge :source="q?.source" :creator-name="q?.creatorName" :creator-id="q?.creatorId" :post-id="q?.postId" :version="q?.version"/><p v-if="error" class="notice" role="alert">{{error}}</p><template v-if="session.done"><h2>풀이 결과</h2><div class="stats"><span>정답<b>{{session.result.correct}}개</b></span><span>오답<b>{{session.result.wrong}}개</b></span><span>점수<b>{{session.result.score}}점</b></span><span>획득 포인트<b>{{session.result.coins}} P</b></span></div><p>자기 문제·이미 보상받은 원본은 미지급이며 일일 한도가 적용됩니다.</p><RouterLink class="button light" to="/pet/mistakes">오답노트</RouterLink><button @click="emit('exit')">문제 목록으로</button></template><template v-else><p class="eyebrow">STUDENT QUEST / 1 OF 1</p><h2>{{q.prompt}}</h2><form @submit.prevent="command('submit')"><fieldset v-if="q.type==='multiple'" class="study-options" :disabled="busy||!!submitted"><legend class="sr-only">정답 선택</legend><label v-for="o in q.options" :key="o.id" class="study-option"><input v-model="answer" type="radio" :value="o.id" :name="q.id"/><span>{{o.text}}</span></label></fieldset><label v-else>답 입력<input v-model="answer" :disabled="busy||!!submitted" maxlength="200" autocomplete="off" required/></label><button v-if="!submitted" :disabled="busy||!answer.trim()">{{busy?'채점 중…':'답안 제출'}}</button></form><section v-if="submitted" class="study-feedback" role="status"><h3>{{submitted.correct?'정답이에요!':'다시 도전해 보세요!'}}</h3><p>내 답: {{submitted.answerText}}</p><p>정답: {{correct}}</p><p>{{q.explanation}}</p><p>{{submitted.awarded??0}} P 획득</p><button :disabled="busy" @click="command('next')">결과 보기</button></section><button class="text-button" @click="emit('exit')">← 문제 목록으로</button></template></section></template>
